mapper.select:
select *
from number_cube_task
where organization_id = #{organizationId}

    and province = #{request.province}


    and city = #{request.city}


    and create_time >= #{request.createTimeStart}


    and create_time <= #{request.createTimeEnd}

order by
    case status
        when 'RUNNING' then 1
        when 'PENDING' then 2
        when 'FAILED' then 3
        when 'SUCCESS' then 4
        else 5
    end,
    create_time desc
